window.RTLBenchLSData.register("assets/d3cd5221d3356bd567495dd195033eff040e324aa759a63037ed685970dad6a8.txt","module mg_10362(input clk,input incdec,input stop,input rst,output [7:0] gray,output [7:0] normal);\nparameter CLK_DIV = 17_000_000; \n  reg [31:0] clkDiv = 32'd0; \n  reg [7:0] curGray = 8'b0; \n  reg [7:0] curNum = 8'b0; \n  assign gray = curGray; \n  assign normal = curNum; \n  always @(posedge clk) \n  begin \n  clkDiv = clkDiv + 1; \n  if (rst == 1) begin \n  clkDiv = 0; \n  curNum = 8'b0; \n  end else if (stop == 1) \n  clkDiv = clkDiv - 1; \n  else if (clkDiv == CLK_DIV) \n  begin \n  clkDiv = 0; \n  if (incdec == 1) \n  curNum = curNum + 1; \n  else \n  curNum = curNum - 1; \n  end \n  curGray = curNum ^ (curNum >> 1); \n  end \n endmodule");
